import itertools

def can_alice_win(N, n, max_rounds=20):
    # Initial distributions
    for start_dist in itertools.product(range(1, n + 1), repeat=N):
        if sum(start_dist) != n:
            continue

        current_dist = list(start_dist)
        possible = True

        # This is a simplification. Alice needs to be able to respond to ANY sequence of Bob's moves.
        # So we need a recursive check or a state-space search.

        def check_state(dist, rounds_left):
            if rounds_left == 0:
                return True

            # Bob tries all possible k
            for k in range(1, N):
                # Alice tries both sigma
                can_respond = False
                for sigma in [1, -1]:
                    # New distribution
                    new_dist = []
                    valid_move = True
                    for i in range(N):
                        val = dist[i] + (sigma if i < k else -sigma)
                        if val < 1:
                            valid_move = False
                            break
                        new_dist.append(val)

                    if valid_move:
                        if check_state(tuple(new_dist), rounds_left - 1):
                            can_respond = True
                            break

                if not can_respond:
                    return False
            return True

        if check_state(tuple(current_dist), max_rounds):
            return True
    return False

